const fs=require('node:fs');const assert=require('node:assert/strict');const ts=require('typescript');
const mod={exports:{}};const source=fs.readFileSync('lib/enderecoObra.ts','utf8');const js=ts.transpileModule(source,{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2020}}).outputText;new Function('module','exports',js)(mod,mod.exports);
